"""Sanity check of the cube code path: boundary data generated by a dipole
inside the cube, so the exact exterior field is known and smooth."""
import numpy as np
from pec_sphere_convergence import dyadic
import pec_cube_lightning as c

y0 = np.array([[0.05, -0.03, 0.08]])
a0 = np.array([[1.0, 0.5j, -0.7]])
inc = lambda pts: -np.einsum("pnab,nb->pa", dyadic(pts, y0, c.K), a0)   # so that E_sc = dipole field
test = c.make_test(inc)
exact = -inc(test["far_pts"])
for n in (3, 4, 6, 8):
    r, far = c.solve(c.base_sources(n, 0.2), 0, 3, test, inc)
    print(f"n={n} N={r['N']:4d} bc_l2={r['bc_l2']:.2e} far_err={np.linalg.norm(far-exact)/np.linalg.norm(exact):.2e}", flush=True)
